          q: { q: 'ما المجموعة التي وصفتها المذكرة بأنها «أساس الحكم ومعرفة النتيجة»؟', o: ['المجموعة الضابطة', 'المجموعة التجريبية', 'العوامل المؤثرة', 'العامل التابع'], a: 0 }
