        { q: 'لماذا ظهر مسمى «المنهج شبه التجريبي»؟', o: ['لصعوبة ضبط المتغيرات وعزلها في الظواهر الإنسانية', 'لأن التجريبي محرم شرعًا', 'لأن الوصفي لا يصلح للاقتصاد', 'لقلة المختبرات'], a: 0 },
        { q: 'يقوم البحث التجريبي على:', o: ['قانون المتغير الواحد', 'قاعدة تعدد الحقيقة', 'تحليل القصة', 'كرة الثلج'], a: 0 }
